//! Terms grammar goldens (1.9.0): the Rust parser is held to the same parses,
//! rejections, canonical text, and keyword vocabulary as `eltq.terms`
//! (`fixtures/golden/terms_parse.json`, regenerated by
//! `uv run python fixtures/generate_fixtures.py`).

use std::path::PathBuf;

use eltq_core::terms::{KEYWORDS, parse_terms_line};

fn golden() -> serde_json::Value {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/golden/terms_parse.json");
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

#[test]
fn parses_match_python() {
    let golden = golden();
    for case in golden["ok"].as_array().unwrap() {
        let line = case["line"].as_str().unwrap();
        let t = parse_terms_line(line).unwrap_or_else(|e| panic!("{line}: {e}"));
        assert_eq!(t.unit_id, case["unit_id"].as_str().unwrap());
        match case["limit"].as_f64() {
            None => assert!(t.limit.is_infinite(), "{line}"),
            Some(limit) => assert_eq!(t.limit, limit, "{line}"),
        }
        assert_eq!(t.ded, case["ded"].as_f64().unwrap());
        let clauses = case["clauses"].as_array().unwrap();
        assert_eq!(t.clauses.len(), clauses.len(), "{line}");
        for (c, want) in t.clauses.iter().zip(clauses) {
            let want = want.as_array().unwrap();
            assert_eq!(c.share, want[0].as_f64().unwrap(), "{line}");
            assert_eq!(c.limit, want[1].as_f64().unwrap(), "{line}");
            assert_eq!(c.attach, want[2].as_f64().unwrap(), "{line}");
        }
        assert_eq!(t.text(), case["text"].as_str().unwrap(), "{line}");
    }
}

#[test]
fn rejections_match_python() {
    for line in golden()["errors"].as_array().unwrap() {
        let line = line.as_str().unwrap();
        assert!(parse_terms_line(line).is_err(), "expected rejection: {line:?}");
    }
}

#[test]
fn keyword_vocabulary_matches_python() {
    let mut want: Vec<String> = golden()["keywords"]
        .as_array()
        .unwrap()
        .iter()
        .map(|k| k.as_str().unwrap().to_string())
        .collect();
    want.sort();
    let mut have: Vec<String> = KEYWORDS.iter().map(|k| k.to_string()).collect();
    have.sort();
    assert_eq!(have, want);
}
